"""Web server: the phone/web app + JSON API. Starts the background worker."""
import base64
import hashlib
import hmac
import json
import os
import time
import urllib.parse
from http.cookies import SimpleCookie
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

import bot
from store import DEFAULT_TIMES, SECRET_KEYS, Store, now

BASE = Path(__file__).resolve().parent
DATA_DIR = Path(os.environ.get("DATA_DIR", BASE / "data"))
DATA_DIR.mkdir(parents=True, exist_ok=True)
PASSWORD = os.environ.get("APP_PASSWORD", "")
SECRET = (os.environ.get("SESSION_SECRET") or hashlib.sha256(("rp:" + PASSWORD).encode()).hexdigest()).encode()
SESSION_DAYS = 60

store = Store(DATA_DIR / "repost.db")
engine = bot.Engine(store, DATA_DIR)

# Web files are built in, so the app works even if the static/ folder wasn't uploaded
_EMBEDDED = {
    "index.html": "",
    "manifest.json": "",
    "icon.svg": "",
}


def static_file(name):
    for path in (BASE / "static" / name, BASE / name):
        if path.exists():
            return path.read_bytes()
    return base64.b64decode(_EMBEDDED[name])


def public_url():
    if os.environ.get("PUBLIC_URL"):
        return os.environ["PUBLIC_URL"].rstrip("/")
    if os.environ.get("RAILWAY_PUBLIC_DOMAIN"):
        return "https://" + os.environ["RAILWAY_PUBLIC_DOMAIN"]
    return f"http://localhost:{os.environ.get('PORT', '8080')}"


def make_session():
    exp = str(int(time.time()) + SESSION_DAYS * 86400)
    return exp + "." + hmac.new(SECRET, exp.encode(), "sha256").hexdigest()


def valid_session(tok):
    try:
        exp, sig = tok.split(".", 1)
        good = hmac.new(SECRET, exp.encode(), "sha256").hexdigest()
        return hmac.compare_digest(sig, good) and int(exp) > time.time()
    except Exception:
        return False


def clean_times(times):
    out = []
    for t in times or []:
        t = str(t).strip()[:5]
        if not t:
            continue
        if not bot.valid_time(t):
            raise ValueError(f"'{t}' isn't a valid time")
        if t not in out:
            out.append(t)
    return sorted(out)


class Handler(BaseHTTPRequestHandler):
    server_version = "RepostApp"

    def log_message(self, fmt, *args):
        pass

    def send(self, code, body=b"", ctype="application/json", headers=None):
        if isinstance(body, (dict, list)):
            body = json.dumps(body).encode()
        elif isinstance(body, str):
            body = body.encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def authed(self):
        c = SimpleCookie(self.headers.get("Cookie", ""))
        return "session" in c and valid_session(c["session"].value)

    def body(self):
        n = int(self.headers.get("Content-Length") or 0)
        if n > 200_000:
            raise ValueError("too large")
        return json.loads(self.rfile.read(n) or b"{}")

    def cookie(self, value, max_age):
        secure = "; Secure" if public_url().startswith("https") else ""
        return f"session={value}; Path=/; HttpOnly; SameSite=Lax; Max-Age={max_age}{secure}"

    def do_HEAD(self):
        self.do_GET()

    def do_GET(self):
        p = urllib.parse.urlparse(self.path).path
        if p == "/health":
            return self.send(200, {"ok": True})
        if p in ("/", "/index.html"):
            return self.send(200, static_file("index.html"), "text/html; charset=utf-8")
        if p == "/manifest.json":
            return self.send(200, static_file("manifest.json"), "application/manifest+json")
        if p == "/icon.svg":
            return self.send(200, static_file("icon.svg"), "image/svg+xml")
        if p == "/api/state":
            if not self.authed():
                return self.send(401, {"error": "login"})
            return self.send(200, self.state())
        return self.send(404, {"error": "not found"})

    def do_POST(self):
        p = urllib.parse.urlparse(self.path).path
        try:
            data = self.body()
        except Exception:
            return self.send(400, {"error": "bad request"})
        if p == "/api/login":
            if PASSWORD and hmac.compare_digest(str(data.get("password", "")), PASSWORD):
                return self.send(200, {"ok": True}, headers={"Set-Cookie": self.cookie(make_session(), SESSION_DAYS * 86400)})
            time.sleep(1.5)
            return self.send(401, {"error": "Wrong password" if PASSWORD else "Set APP_PASSWORD in Railway first"})
        if not self.authed():
            return self.send(401, {"error": "login"})
        if p == "/api/logout":
            return self.send(200, {"ok": True}, headers={"Set-Cookie": self.cookie("", 0)})
        try:
            result = self.api(p, data)
        except (ValueError, RuntimeError) as e:
            return self.send(400, {"error": str(e)})
        if result is None:
            return self.send(404, {"error": "not found"})
        return self.send(200, result)

    # ---------------------------------------------------------------- API
    def api(self, p, d):
        s = store.settings()
        ver = s["ig_graph_version"]

        if p == "/api/settings":
            clean = {}
            if "paused" in d:
                clean["paused"] = bool(d["paused"])
            if "timezone" in d:
                tz = str(d["timezone"]).strip()
                try:
                    from zoneinfo import ZoneInfo
                    ZoneInfo(tz)
                except Exception:
                    raise ValueError(f"Unknown time zone '{tz}'")
                clean["timezone"] = tz
            if "scan_depth" in d:
                clean["scan_depth"] = max(3, min(50, int(d["scan_depth"])))
            if "caption_template" in d:
                clean["caption_template"] = str(d["caption_template"])
            if "credit_format" in d:
                if "{handle}" not in d["credit_format"]:
                    raise ValueError("Credit format needs {handle} in it")
                clean["credit_format"] = str(d["credit_format"]).strip()
            if "ig_reader_username" in d:
                clean["ig_reader_username"] = str(d["ig_reader_username"]).strip().lstrip("@")
            if d.get("ig_sessionid"):
                clean["ig_sessionid"] = str(d["ig_sessionid"]).strip()
            store.set_settings(clean)
            return {"ok": True}

        if p == "/api/settings/clear-reader":
            store.set_settings({"ig_sessionid": "", "ig_reader_username": ""})
            return {"ok": True}

        # ---- accounts ----
        if p == "/api/accounts/save":
            times = clean_times(d.get("times"))
            name = (d.get("name") or "").strip()
            ig_id = (d.get("ig_user_id") or "").strip()
            token = (d.get("access_token") or "").strip()
            if d.get("id"):
                acc = store.account(d["id"])
                if not acc:
                    raise ValueError("account not found")
                new = dict(acc, ig_user_id=ig_id or acc["ig_user_id"], access_token=token or acc["access_token"])
                username = acc["username"]
                if token or ig_id != acc["ig_user_id"]:
                    username = bot.account_username(ver, new)  # proves the token works
                store.x("UPDATE accounts SET name=?, username=?, ig_user_id=?, access_token=?, times=?, enabled=? WHERE id=?",
                        (name or username or acc["name"], username, new["ig_user_id"], new["access_token"],
                         json.dumps(times), int(bool(d.get("enabled", True))), acc["id"]))
            else:
                if not (ig_id and token):
                    raise ValueError("Add the Instagram account ID and access token")
                username = bot.account_username(ver, {"ig_user_id": ig_id, "access_token": token})
                store.x("INSERT INTO accounts(name, username, ig_user_id, access_token, times, enabled, created_at)"
                        " VALUES (?,?,?,?,?,1,?)", (name or "@" + username, username, ig_id, token, json.dumps(times), now()))
                store.log("info", f"Connected Instagram @{username}")
            return {"ok": True}

        if p == "/api/accounts/delete":
            store.x("DELETE FROM accounts WHERE id=?", (d.get("id"),))
            store.x("UPDATE creators SET account_id=NULL WHERE account_id=?", (d.get("id"),))
            return {"ok": True}

        if p == "/api/accounts/discover":
            token = (d.get("token") or "").strip()
            if not token:
                raise ValueError("Paste a token first")
            found = bot.discover_accounts(ver, token)
            if not found:
                raise ValueError("No Instagram accounts found. Make sure you picked your Pages AND Instagram accounts when generating the token.")
            existing = {a["ig_user_id"]: a["id"] for a in store.accounts()}
            for f in found:
                f["existing"] = f["ig_user_id"] in existing
            return {"accounts": found}

        if p == "/api/accounts/import":
            existing = {a["ig_user_id"]: a for a in store.accounts()}
            added = updated = 0
            for f in d.get("accounts") or []:
                if f["ig_user_id"] in existing:
                    store.x("UPDATE accounts SET access_token=?, username=? WHERE id=?",
                            (f["access_token"], f.get("username", ""), existing[f["ig_user_id"]]["id"]))
                    updated += 1
                else:
                    store.x("INSERT INTO accounts(name, username, ig_user_id, access_token, times, enabled, created_at)"
                            " VALUES (?,?,?,?,?,1,?)",
                            ("@" + f["username"] if f.get("username") else f.get("page", "Instagram"),
                             f.get("username", ""), f["ig_user_id"], f["access_token"], json.dumps(DEFAULT_TIMES), now()))
                    added += 1
            store.log("info", f"Imported Instagram accounts: {added} added, {updated} updated")
            return {"ok": True, "added": added, "updated": updated}

        if p == "/api/accounts/post-now":
            acc = store.account(d.get("id"))
            if not acc:
                raise ValueError("account not found")
            engine.post_now(acc["id"])
            return {"ok": True}

        # ---- creators ----
        if p == "/api/creators/save":
            src = d.get("pull_from")
            if src not in ("tiktok", "instagram"):
                raise ValueError("Pick where to pull from")
            if not store.account(d.get("account_id")):
                raise ValueError("Pick which of your accounts this creator posts to")
            tt = (d.get("tiktok") or "").strip().lstrip("@")
            ig = (d.get("instagram") or "").strip().lstrip("@")
            if not (tt if src == "tiktok" else ig):
                raise ValueError(f"Add their {'TikTok' if src == 'tiktok' else 'Instagram'} handle")
            name = (d.get("name") or ig or tt).strip()
            fields = (name, src, tt, ig, (d.get("permission") or "").strip(),
                      int(bool(d.get("enabled", True))), int(d["account_id"]))
            if d.get("id"):
                store.x("UPDATE creators SET name=?, pull_from=?, tiktok=?, instagram=?, permission=?, enabled=?, account_id=? "
                        "WHERE id=?", (*fields, d["id"]))
            else:
                store.x("INSERT INTO creators(name, pull_from, tiktok, instagram, permission, enabled, account_id, created_at)"
                        " VALUES (?,?,?,?,?,?,?,?)", (*fields, now()))
                store.log("info", f"Added creator {name}")
            return {"ok": True}

        if p == "/api/creators/delete":
            store.x("DELETE FROM creators WHERE id=?", (d.get("id"),))
            store.x("UPDATE reposts SET status='skipped', error='creator deleted' WHERE creator_id=? AND status='queued'",
                    (d.get("id"),))
            return {"ok": True}

        # ---- reposts ----
        if p == "/api/queue":
            src, pid, url = bot.parse_link(str(d.get("url", "")))
            cr = store.q("SELECT * FROM creators WHERE id=?", (d.get("creator_id"),))
            if not cr:
                raise ValueError("Pick whose video it is (for the credit)")
            cr = cr[0]
            if not cr["account_id"]:
                raise ValueError("That creator isn't assigned to one of your accounts")
            row = store.q("SELECT * FROM reposts WHERE account_id=? AND source=? AND post_id=?", (cr["account_id"], src, pid))
            if row and row[0]["status"] == "posted":
                raise ValueError("That video was already posted to this account")
            if row:
                store.x("UPDATE reposts SET status='queued', attempts=0, error=NULL, manual=1 WHERE id=?", (row[0]["id"],))
            else:
                store.x("INSERT INTO reposts(account_id, creator_id, source, post_id, url, status, manual, created_at)"
                        " VALUES (?,?,?,?,?, 'queued', 1, ?)", (cr["account_id"], cr["id"], src, pid, url, now()))
            return {"ok": True}

        if p == "/api/reposts/retry":
            store.x("UPDATE reposts SET status='queued', attempts=0, error=NULL WHERE id=?", (d.get("id"),))
            return {"ok": True}
        if p == "/api/reposts/skip":
            store.x("UPDATE reposts SET status='skipped' WHERE id=?", (d.get("id"),))
            return {"ok": True}
        return None

    def state(self):
        s = store.settings()
        posted = {r["account_id"]: r["n"] for r in store.q(
            "SELECT account_id, COUNT(*) n FROM reposts WHERE status='posted' GROUP BY account_id")}
        queued = {r["account_id"]: r["n"] for r in store.q(
            "SELECT account_id, COUNT(*) n FROM reposts WHERE status='queued' GROUP BY account_id")}
        ncreators = {r["account_id"]: r["n"] for r in store.q(
            "SELECT account_id, COUNT(*) n FROM creators WHERE enabled=1 GROUP BY account_id")}
        accounts = []
        for a in store.accounts():
            accounts.append({
                "id": a["id"], "name": a["name"], "username": a["username"], "ig_user_id": a["ig_user_id"],
                "connected": bool(a["ig_user_id"] and a["access_token"]), "times": a["times"],
                "enabled": bool(a["enabled"]),
                "next_post": bot.next_post_time(s["timezone"], a["times"]) if a["enabled"] and not s["paused"] else None,
                "posted": posted.get(a["id"], 0), "queued": queued.get(a["id"], 0),
                "creators": ncreators.get(a["id"], 0)})
        creators = store.q(
            "SELECT c.*, (SELECT COUNT(*) FROM reposts r WHERE r.creator_id=c.id AND r.status='posted') AS posted "
            "FROM creators c ORDER BY c.name COLLATE NOCASE")
        reposts = store.q(
            "SELECT r.id, r.source, r.url, r.status, r.attempts, r.error, r.manual, r.created_at, r.posted_at, "
            "c.name AS creator, a.name AS account FROM reposts r "
            "LEFT JOIN creators c ON c.id=r.creator_id LEFT JOIN accounts a ON a.id=r.account_id "
            "WHERE r.status IN ('posted','failed','queued','posting') "
            "ORDER BY COALESCE(r.posted_at, r.created_at) DESC LIMIT 60")
        since = time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(time.time() - 86400))
        settings = {k: (bool(v) if k in SECRET_KEYS else v) for k, v in s.items()}
        return {
            "status": engine.status,
            "settings": settings,
            "accounts": accounts,
            "creators": creators,
            "reposts": reposts,
            "events": store.q("SELECT ts, level, msg FROM events ORDER BY id DESC LIMIT 40"),
            "counts": {"posted": sum(posted.values()),
                       "last24h": store.q("SELECT COUNT(*) n FROM reposts WHERE status='posted' AND posted_at>=?",
                                          (since,))[0]["n"]},
        }


def main():
    if not PASSWORD:
        print("WARNING: APP_PASSWORD isn't set, so nobody can log in until you add it.", flush=True)
    engine.start()
    port = int(os.environ.get("PORT", "8080"))
    print(f"Repost app running on port {port} ({public_url()})", flush=True)
    ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()


if __name__ == "__main__":
    main()
